   cloze('أكمل عائلة الاستدراك', 'لا أعارض الزيادة، ___ أعارض طريقتها. المقترح جيّد، ___ توقيته سيّئ. ليس المهمّ كم نقرأ، ___ المهمّ كيف.', ['بل', 'لكنّ', 'وإنّما'], ['أمّا', 'لأنّ']),
