   cloze('أكمل عائلة التفصيل', '___ القاعة فجاهزة، وأمّا المعلّم ___ السؤال. ___ الآن وإمّا بعد رمضان.', ['أمّا', 'فهو', 'إمّا'], ['بل', 'إنّما']),
   cloze('أكمل تحويل سالم', 'لا أعارض القاعة المسائية، ___ أعارض أن تبدأ في رمضان؛ ___ تنجح إذا كان لها معلّم غير متعب؛ ___ الموعد فبعد رمضان.', ['بل', 'إنّما', 'أمّا'], ['لكنّ', 'إمّا']),
   tf('بل بعد الإثبات تنفي ما قبلها.', 'هند: قرأتُ المذكّرة، بل قرأتُها مرّتين. كلير: أبقيتِها وزدتِ عليها.', 'false', 'بعد الإثبات تُبقي وتزيد؛ النفي يكون مع بل بعد لا أو ليس.'),
   tf('يأتي بعد لا سيّما اسم لا فعل.', 'هند: ولا تأتي بعدها جملة فعلية مباشرة. ماريا: اسم بعدها، لا فعل.', 'true', 'لا سيّما الطلّاب الذين يذهبون مساءً، لا: لا سيّما يذهب الطلّاب.'),
   tf('يجوز حذف الفاء من جواب أمّا في الكلام السريع.', 'هند: القاعدة الذهبية: لا أمّا بلا فاء في جوابها.', 'false', 'لا تسقط الفاء أبدًا؛ كين صحّح: أمّا الطلّاب فيريدون.'),
   tap('المس بل التي بعد الإثبات', ['قرأتُ', 'المذكّرة،', 'بل', 'قرأتُها', 'مرّتين', 'أمس'], 'بل'),
